function validate(input) {
  const [functions] = input;
  if (!Array.isArray(functions) || functions.length < 1 || functions.length > 10) return 'Give 1 to 10 functions.';
  for (const spec of functions) {
    if (!spec || typeof spec !== 'object' || Array.isArray(spec)) return 'Each function must be an object such as { "t": 100, "resolve": 5 }.';
    if (!Number.isInteger(spec.t) || spec.t < 0 || spec.t > 1000) return 'Each function needs a time t from 0 to 1000.';
    const keys = Object.keys(spec).sort().join(',');
    if (keys === 'resolve,t') {
      if (!Number.isInteger(spec.resolve) || spec.resolve < -1000 || spec.resolve > 1000) return 'resolve must be an integer from -1000 to 1000.';
    } else if (keys === 'reject,t') {
      if (typeof spec.reject !== 'string' || spec.reject.length < 1 || spec.reject.length > 20) return 'reject must be a string of 1 to 20 characters.';
    } else return 'Each function needs t and exactly one of resolve or reject.';
  }
  return null;
}

