function adapt(input, solve, kit) {
  const [specs] = input;
  const functions = specs.map((spec, index) => () => {
    kit.trace(`functions[${index}] is called`);
    const failing = spec.reject !== undefined;
    const outcome = failing ? spec.reject : spec.resolve;
    const settle = () => kit.trace(`The promise of functions[${index}] ${failing ? 'rejects' : 'resolves'} with ${JSON.stringify(outcome)}`);
    if (spec.t === 0) {
      settle();
      return failing ? Promise.reject(outcome) : Promise.resolve(outcome);
    }
    return new Promise((resolve, reject) => setTimeout(() => {
      settle();
      if (failing) reject(outcome);
      else resolve(outcome);
    }, spec.t));
  });
  const start = Date.now();
  kit.trace(`promiseAll is called with ${specs.length} function${specs.length === 1 ? '' : 's'}`);
  // The exercise asks for a solution without the built-in Promise.all.
  const builtin = Promise.all;
  Promise.all = () => { throw new Error('Solve this without the built-in Promise.all.'); };
  let promise;
  try { promise = solve(functions); } finally { Promise.all = builtin; }
  if (!promise || typeof promise.then !== 'function') throw new Error('promiseAll must return a promise.');
  return promise.then((values) => {
    kit.trace(`The returned promise resolves with ${JSON.stringify(values)}`);
    return { t: Date.now() - start, resolved: values };
  }, (reason) => {
    const rejected = reason instanceof Error ? String(reason) : reason;
    kit.trace(`The returned promise rejects with ${JSON.stringify(rejected)}`);
    return { t: Date.now() - start, rejected };
  });
}

