async function promiseAll(functions) {
  const tagged = functions.map((fn, index) => fn().then((value) => ({ index, value })));
  const values = [];
  const done = new Set();
  while (done.size < functions.length) {
    const open = tagged.filter((_, index) => !done.has(index));
    const first = await Promise.race(open);
    done.add(first.index);
    values[first.index] = first.value;
  }
  return values;
}

