function generate(rand, size) {
  const count = size === 'small' ? 1 + Math.floor(rand() * 4) : 6 + Math.floor(rand() * 5);
  const maxTime = size === 'small' ? 120 : 1000;
  const failing = rand() < 0.5;
  const functions = [];
  for (let i = 0; i < count; i++) {
    const roll = rand();
    const t = roll < 0.1 ? 0 : Math.floor(rand() * (maxTime + 1));
    if (failing && rand() < 0.4) functions.push({ t, reject: `Error ${i}` });
    else functions.push({ t, resolve: Math.floor(rand() * (size === 'small' ? 21 : 2001)) - (size === 'small' ? 10 : 1000) });
  }
  if (failing && !functions.some((spec) => spec.reject !== undefined)) {
    const index = Math.floor(rand() * count);
    functions[index] = { t: functions[index].t, reject: `Error ${index}` };
  }
  return [functions];
}
